package com.uop.recordingtools.service;
import com.uop.recordingtools.util.Items; import org.bukkit.enchantments.Enchantment; import org.bukkit.entity.Player; import org.bukkit.inventory.ItemStack; import java.util.*;
public final class EnchantService{public void apply(Player p,String scope,Enchantment e,int level,String slot){for(ItemStack i:items(p,scope,slot))if(i!=null&&!i.getType().isAir())Items.enchant(i,e,level);}public void remove(Player p,String scope,Enchantment e,String slot){for(ItemStack i:items(p,scope,slot))if(i!=null)Items.clearEnchantment(i,e);}private List<ItemStack> items(Player p,String scope,String slot){var inv=p.getInventory();List<ItemStack> out=new ArrayList<>();switch(scope.toLowerCase(Locale.ROOT)){case "all"->{out.addAll(Arrays.asList(inv.getContents()));out.addAll(Arrays.asList(inv.getArmorContents()));out.add(inv.getItemInOffHand());}case "armor"->{switch(slot==null?"all":slot.toLowerCase()){case "head"->out.add(inv.getHelmet());case "chest"->out.add(inv.getChestplate());case "legs"->out.add(inv.getLeggings());case "feet"->out.add(inv.getBoots());default->out.addAll(Arrays.asList(inv.getArmorContents()));}}case "equipment"->{out.addAll(Arrays.asList(inv.getArmorContents()));out.add(inv.getItemInMainHand());out.add(inv.getItemInOffHand());}case "mainhand"->out.add(inv.getItemInMainHand());case "offhand"->out.add(inv.getItemInOffHand());case "hand"->{if("offhand".equalsIgnoreCase(slot))out.add(inv.getItemInOffHand());else out.add(inv.getItemInMainHand());}case "inventory"->out.addAll(Arrays.asList(inv.getStorageContents()));}return out;}}
